ALTER TABLE public.contas ADD COLUMN IF NOT EXISTS obra_id uuid REFERENCES public.obras(id), ADD COLUMN IF NOT EXISTS numero_documento text;
ALTER TABLE public.lancamentos_financeiros ADD COLUMN IF NOT EXISTS obra_id uuid REFERENCES public.obras(id), ADD COLUMN IF NOT EXISTS numero_documento text;
ALTER TABLE public.ordens_servico ADD COLUMN IF NOT EXISTS materiais_utilizados text, ADD COLUMN IF NOT EXISTS horas_trabalhadas numeric NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS aceite_observacoes text, ADD COLUMN IF NOT EXISTS aceite_em timestamptz;
ALTER TABLE public.vendas ADD COLUMN IF NOT EXISTS endereco_entrega text;
CREATE TABLE public.despesas_recorrentes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), descricao text NOT NULL, parceiro text, categoria text NOT NULL, valor numeric NOT NULL CHECK (valor > 0), dia_vencimento integer NOT NULL CHECK (dia_vencimento BETWEEN 1 AND 31), inicio date NOT NULL, fim date, ativo boolean NOT NULL DEFAULT true, obra_id uuid REFERENCES public.obras(id), created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.despesas_recorrentes TO authenticated; GRANT ALL ON public.despesas_recorrentes TO service_role;
ALTER TABLE public.despesas_recorrentes ENABLE ROW LEVEL SECURITY;
CREATE POLICY recorrencias_financeiro ON public.despesas_recorrentes FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'gerente') OR public.has_role(auth.uid(),'financeiro')) WITH CHECK (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'gerente') OR public.has_role(auth.uid(),'financeiro'));
CREATE TRIGGER recorrencias_updated BEFORE UPDATE ON public.despesas_recorrentes FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
ALTER TABLE public.contas ADD COLUMN IF NOT EXISTS recorrencia_id uuid REFERENCES public.despesas_recorrentes(id), ADD COLUMN IF NOT EXISTS competencia_recorrencia date;
CREATE UNIQUE INDEX contas_recorrencia_competencia ON public.contas(recorrencia_id, competencia_recorrencia) WHERE recorrencia_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.gerar_despesas_recorrentes() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE qtd integer; BEGIN INSERT INTO public.contas(tipo,descricao,parceiro,categoria,valor,vencimento,status,obra_id,recorrencia_id,competencia_recorrencia,created_by) SELECT 'pagar', r.descricao,r.parceiro,r.categoria,r.valor, least((m + (r.dia_vencimento-1)*interval '1 day')::date,(m + interval '1 month - 1 day')::date),'aberto',r.obra_id,r.id,m::date,r.created_by FROM public.despesas_recorrentes r CROSS JOIN LATERAL generate_series(date_trunc('month',r.inicio::timestamp),date_trunc('month',least(coalesce(r.fim,current_date),current_date)::timestamp),interval '1 month') m WHERE r.ativo AND least((m + (r.dia_vencimento-1)*interval '1 day')::date,(m + interval '1 month - 1 day')::date) >= r.inicio AND (r.fim IS NULL OR least((m + (r.dia_vencimento-1)*interval '1 day')::date,(m + interval '1 month - 1 day')::date)<=r.fim) ON CONFLICT DO NOTHING; GET DIAGNOSTICS qtd = ROW_COUNT; RETURN qtd; END $$;
REVOKE ALL ON FUNCTION public.gerar_despesas_recorrentes() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.gerar_despesas_recorrentes() TO service_role;
CREATE EXTENSION IF NOT EXISTS pg_cron;
SELECT cron.schedule('splash-despesas-mensais','5 6 * * *','SELECT public.gerar_despesas_recorrentes()');